#define SUPERBLOCK_MAGIC 0x1337C0DE

typedef struct {
    unsigned int s_magic;           // Filesystem Identifier
    unsigned int s_block_size;      // Size of data blocks (bytes)
    unsigned int s_total_blocks;    // Total size of the volume
    unsigned int s_total_inodes;    // Total available inodes

    unsigned int s_free_blocks;
    unsigned int s_first_data_block;
    unsigned int s_inode_table_start; // Block where inodes begin

    short s_state;                  // FS state (Clean/Dirty)
    short s_padding;
} superblock_t;

// Superblock is usually located at a known offset (e.g., block 1024 bytes into the partition).
